validator:
function validate(input) {
  const [{ ActorDirector = [] }] = input;
  const stamps = new Set();
  for (const [actor, director, stamp] of ActorDirector) {
    if (actor === null || director === null) return 'Every row needs an actor_id and a director_id.';
    if (stamp === null) return 'Every row needs a timestamp.';
    if (stamps.has(stamp)) return `timestamp ${stamp} appears twice.`;
    stamps.add(stamp);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 2000;
  // Few people in small tables make pairs repeat; a large table spreads 2,000 rows over about 150 pairs.
  const people = small ? 3 : 12;
  const ActorDirector = [];
  const stamps = Array.from({ length: count }, (_, i) => i);
  for (let i = stamps.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [stamps[i], stamps[j]] = [stamps[j], stamps[i]];
  }
  for (let i = 0; i < count; i++) {
    ActorDirector.push([1 + Math.floor(rand() * people), 1 + Math.floor(rand() * people), stamps[i]]);
  }
  return [{ ActorDirector }];
}
